const DICTS: Record<Lang, Record<string, string>> = { ru: {}, tg, ky, uz };

const STORAGE_KEY = "aloqa_lang";

let current: Lang = "ru";

export function getLang(): Lang {
  return current;
}

export function loadLang(): Lang {
  try {
    const v = localStorage.getItem(STORAGE_KEY) as Lang | null;
    if (v && ["ru", "tg", "ky", "uz"].includes(v)) current = v;
  } catch {
    /* ignore */
  }
  return current;
}

export function setLang(l: Lang) {
  current = l;
  try {
    localStorage.setItem(STORAGE_KEY, l);
  } catch {
    /* ignore */
  }
}

/** Translate a Russian source string into the active language. */
export function t(ru: string): string {
  if (current === "ru") return ru;
  return DICTS[current][ru] ?? ru;
}
